def sha(text):
    return hashlib.sha256(text.encode('utf-8')).hexdigest()


def make_source(theme, number, split):
    sid = 'lcv1-' + theme + '-' + str(number + 1)
    paragraphs = ANNEX[theme]
    detail = DETAILS[theme][number].split('\n\n')
    early, late = FACTS[theme][number]
    parts = [('intro', detail[0]), ('handbook-a', '\n\n'.join(paragraphs[:2])),
             *early, ('handbook-b', '\n\n'.join(paragraphs[2:])), ('work-note', detail[1]),
             ('closing-context', detail[2]), *late]
    body, offsets = '', {}
    for key, text in parts:
        if body:
            body += '\n\n'
        start = len(body)
        body += text
        if key not in {'intro', 'handbook-a', 'handbook-b', 'work-note', 'closing-context'}:
            offsets[key] = {'source_id': sid, 'start': start, 'end': len(body), 'quote_sha256': sha(text)}
    if not 4000 <= len(body) <= 12000:
        raise PLMError('long-context source length outside fixed range: ' + sid)
    source = {'source_id': sid, 'project': 'long-context-' + theme, 'split': split,
        'title': theme.title() + ' work record ' + str(number + 1), 'body': body,
        'observed_at': '2026-06-10T00:00:00Z', 'scope': 'session' if number == 2 else 'project',
        'scope_id': {'harbor':'lantern-lab','museum':'dry-glass','rail':'cedar-night','festival':'mosslight-preview'}[theme] if number == 2 else '', 'tags': []}
    return source, offsets


