def payload():
    sources, questions, offsets, groups = [], [], {}, []
    for theme in ('harbor','museum','rail','festival'):
        split = 'dev' if theme in {'harbor','museum'} else 'heldout'
        for number in range(3):
            source, spans = make_source(theme, number, split)
            sources.append(source)
            offsets.update(spans)
        groups.append({'parent_event_group': theme, 'project': 'long-context-' + theme, 'split': split})
        for number, row in enumerate(QUESTIONS[theme], 1):
            category, query, answer, alternative, points, keys, *scope = row
            qid = 'lcv1-' + theme + '-q' + str(number)
            scoped = scope == ['session']
            scope_id = sources[-1]['scope_id'] if scoped else ''
            questions.append({'question_id': qid, 'project': 'long-context-' + theme, 'split': split,
                'category': category, 'question': query, 'question_date': '2026-06-10', 'answer': answer,
                'acceptable_answers': [answer, alternative], 'required_points': [{'id': point, 'description': point, 'any_of': alternatives} for point, alternatives in points],
                'forbidden_claims': [], 'required_source_ids': list(dict.fromkeys(offsets[key]['source_id'] for key in keys)),
                'unanswerable': not keys, 'scope': 'session' if scoped else 'project', 'scope_id': scope_id,
                'evidence_keys': keys})
    return sources, questions, offsets, groups


def build(output):
    output = Path(output)
    sources, authored, offsets, groups = payload()
    questions = [{key:value for key,value in row.items() if key != 'evidence_keys'} for row in authored]
    metadata = {'dataset_id':'plm-long-context-synthetic-v1-24', 'origin':'authored_synthetic_long_context_not_real_user_tasks',
        'splits':['dev','heldout'], 'synthetic':True, 'real_user_query_sample':False, 'official_benchmark_score':False,
        'questions':24, 'source_count':12, 'parent_event_groups':groups, 'selected_using_predictions':False,
        'body_length_unit':'Unicode code points', 'shared_appendix':'same-theme handbook context repeated within one parent-event group only; no cross-split theme sharing',
        'evidence_span_usage':'evaluator only, never supplied to ingestion/retrieval/reader', 'builder_sha256':hashlib.sha256(Path(__file__).read_bytes()).hexdigest()}
    write_dataset(output, sources, questions, metadata)
    manifest = json.loads((output/'manifest.json').read_text())
    for split in ('dev','heldout'):
        rows = []
        for question in (row for row in authored if row['split'] == split):
            rows.append({'question_id':question['question_id'], 'unanswerable':question['unanswerable'],
                'spans':[{'evidence_id':key, **offsets[key]} for key in question['evidence_keys']],
                'absence_check_source_ids': [source['source_id'] for source in sources if source['project']==question['project'] and source['scope']==question['scope'] and source['scope_id']==question['scope_id']] if question['unanswerable'] else [],
                'absence_policy':'exhaustive authored in-scope record contains no requested value; no fabricated positive evidence span' if question['unanswerable'] else None})
        sidecar = {'schema_version':1, 'dataset_id':metadata['dataset_id'], 'split':split,
            'sources_sha256':manifest['sha256']['sources.json'], 'questions_sha256':manifest['sha256']['questions.'+split+'.json'],
            'offset_unit':'Unicode code points; start inclusive/end exclusive; hash of quote.encode(utf-8)', 'retrieval_use_forbidden':True, 'questions':rows}
        (output/('evidence-spans.'+split+'.json')).write_text(json.dumps(sidecar,ensure_ascii=False,sort_keys=True,indent=2)+'\n',encoding='utf-8')
    extra = {'builder_sha256':metadata['builder_sha256'], 'dataset_manifest_sha256':sha((output/'manifest.json').read_text()),
        'sidecar_sha256':{name:sha((output/name).read_text()) for name in ('evidence-spans.dev.json','evidence-spans.heldout.json')}}
    (output/'provenance.json').write_text(json.dumps(extra,sort_keys=True,indent=2)+'\n')
    return {'questions':len(questions),'sources':len(sources),'source_chars_min':min(len(row['body']) for row in sources),
        'source_chars_max':max(len(row['body']) for row in sources),'dataset_fingerprint':fingerprint(manifest)}


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--output',type=Path,required=True)
    args = parser.parse_args()
    print(json.dumps(build(args.output),sort_keys=True))
